"""Analysis artefact generator. Writes only inside this new review workspace.

Run from repository root: python3 docproject/architecture-review/validation/build_review.py
Does not execute application code, mutate specifications, or claim application tests.
"""
from pathlib import Path
import csv, hashlib, json, re

ROOT = Path(__file__).resolve().parents[3]
OUT = ROOT / 'docproject/architecture-review'
SECTIONS = json.loads((OUT/'evidence/sections.json').read_text())
REQS = list(csv.DictReader((ROOT/'docs/registers/requirements.csv').open()))
DOCS = list(csv.DictReader((ROOT/'docs/registers/document-inventory.csv').open()))

def write(path, text):
    p = (OUT/path).resolve()
    assert p.is_relative_to(OUT.resolve())
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(text, encoding='utf-8')

def dump(path, value):
    write(path, json.dumps(value, indent=2, ensure_ascii=False)+'\n')

def table(headers, rows):
    def cell(x): return str(x).replace('|',' / ').replace('\n','<br>')
    return '| '+' | '.join(headers)+' |\n| '+' | '.join('---' for _ in headers)+' |\n'+''.join('| '+' | '.join(cell(x) for x in row)+' |\n' for row in rows)

def source(path, needle=None):
    lines=(ROOT/path).read_text().splitlines()
    line=next((n+1 for n,x in enumerate(lines) if needle and needle in x),1)
    return {'path':path,'line':line,'quote':lines[line-1].strip()[:450], 'needle':needle, 'matched':needle is None or any(needle in x for x in lines)}

def slink(s, prefix='../../'):
    return f"[{s['path']}:{s['line']}]({prefix}{s['path']})"

def evidence(path, needle=None):
    s=source(path,needle)
    candidates=[e for e in SECTIONS if e['path']==path and e['start_line']<=s['line']<=e['end_line']]
    return candidates[-1]['evidence_id'] if candidates else 'HPX-EV-EXT-'+hashlib.sha256(path.encode()).hexdigest()[:12]

# Status is temporal, not an assertion of end-to-end acceptance.
LOCAL='L — documented local implementation; historical checks reported, not rerun'
GATED='G — accepted design / gated local code; actual runtime integration pending'
FUTURE='F — future obligation; mechanism incomplete'
DEFER='D — explicitly deferred'

families=[]
def F(num,name,paths,component,security,reads):
    f={'id':f'HPX-PROC-{num:03d}','name':name,'paths':paths,'component':component,'security':security,'reads':reads,'leaves':[]}
    families.append(f)
    return f

def L(f,name,status,inputs,outputs,transform,objects,writes='None',tx='Read-only / no durable transaction',errors='Malformed, stale or unauthorized context fails without mutation',recovery='Retain exact intent; repair or retry only under current authority',invariant='Identity, source bytes and immutable history remain unchanged',code='',tests='',calls=()):
    n=len(f['leaves'])+1
    p={'id':f"{f['id']}.{n:03d}",'name':name,'parent':f['id'],'status':status,'purpose':transform,
       'actors_and_trigger':inputs.split(';')[0], 'preconditions': 'Exact scoped authority and supported version; '+('future mechanism must be approved before use' if status in (FUTURE,DEFER) else 'unlocked workspace for protected data; expected context must match'),
       'inputs':inputs,'outputs':outputs,'transformations':transform,'reads':f['reads'],'writes':writes,'core_objects':objects,
       'invokes':list(calls),'dependencies':f['component'],'state_changes':writes if writes!='None' else 'No persistent state change',
       'transaction':tx,'side_effects': 'Only listed writes/output delivery; no implied provider call or publication',
       'errors':errors,'recovery':recovery,'security':f['security'],'invariants':invariant,
       'specifications':f['paths'],'evidence':[evidence(x) for x in f['paths']],
       'code':code,'tests':tests,'verification':'No application checks executed in this review. '+('No implementation evidence claimed; acceptance cases are proposed.' if not code else 'Static alignment evidence only; prior check scope stays in the cited development/test records.'),
       'open_contract':status in (FUTURE,DEFER)}
    f['leaves'].append(p)
    return p

