# Section ledger is an inventory; selected claims below carry actual semantic classifications.
claims=[]
def C(kind,claim,refs,scope,procs):
    c={'id':f'HPX-CLM-{len(claims)+1:03d}','classification':kind,'claim':claim,'scope':scope,'processes':procs,
       'sources':[source(p,n) for p,n in refs]}
    c['evidence']=[evidence(p,n) for p,n in refs]
    claims.append(c)
    return c['id']

