write('process-inventory.md','# Process inventory — Stage B\n\n'+
      f'{len(families)} parent responsibilities and {len(processes)} leaf processes. IDs are review identifiers, not new HPX object IDs. L = documented local behavior, G = gated local code, F = future incomplete mechanism, D = explicitly deferred. A leaf marked F/D is a reconstruction boundary, not an invented executable contract. Shared calls do not create second parents.\n\n'+
      table(['Parent','Responsibility','Leaves','Catalogue'],[[f['id'],f['name'],len(f['leaves']),f"[Details](process-catalogue/{f['id']}.md)"] for f in families])+ '\n'+
      '\n'.join(f"## {f['id']} — {f['name']}\n\n"+table(['ID','Process','Scope'],[[p['id'],p['name'],p['status'][0]] for p in f['leaves']]) for f in families))

for f in families:
    prefix='../../../'
    text=f"# {f['id']} — {f['name']}\n\n[Inventory](../process-inventory.md) · [Diagram navigation](../diagrams/README.md) · [Machine-readable contracts](../traceability/process-model.json)\n\n"
    parent={'Stable ID':f['id'],'Purpose':f['name'],'Parent':'HPX system boundary','Actors and initiating events':'Union of explicit child triggers; no autonomous background job implied','Preconditions':'Each child retains its own authority, milestone and expected-state constraints','Inputs':'Union of listed child inputs','Outputs':'Union of listed child outputs','Transformations':'Orchestration/decomposition only; parent is not an additional hidden operation','Data read':f['reads'],'Data modified':'Union of listed child writes; no additional parent-owned store','Core objects':'See child contracts; conceptual model and physical storage are distinct','Invoked subprocesses':', '.join(p['id'] for p in f['leaves']),'Dependencies':f['component'],'State transitions':'See child lifecycles; no new aggregate state','Transaction boundaries':'Parent spans multiple operations; no family-wide atomic transaction','Side effects':'Only explicitly listed child effects','Errors':'Propagate child failures without inventing successful outcomes','Recovery':'Child-specific retry/compensation; incomplete future contracts remain open','Security':f['security'],'Requirements':', '.join(sorted(set(r for p in f['leaves'] for r in p['requirements']))),'Specification evidence':'; '.join(slink(source(x),prefix) for x in f['paths']),'Implementation':'Only child code evidence; family coverage is not whole-feature delivery','Verification':'Review structural checks only; prior application tests are reported, not rerun'}
    text+=table(['Parent contract field','Definition'],parent.items())
    labels={'id':'Stable process ID','name':'Name','parent':'Parent process','status':'Applicable milestone/status','purpose':'Purpose','actors_and_trigger':'Actors / initiating event','preconditions':'Preconditions','inputs':'Inputs','outputs':'Outputs','transformations':'Internal transformation','reads':'Data read','writes':'Data modified','core_objects':'Core objects','invokes':'Invoked subprocesses','dependencies':'Dependencies','state_changes':'State changes','transaction':'Transaction boundary','side_effects':'Side effects','errors':'Failure conditions','recovery':'Recovery / compensation','security':'Security / trust','invariants':'Contract / postcondition','requirements':'Requirement seed paths','requirements_note':'Traceability limit','code':'Implementation evidence','tests':'Verification evidence / proposed acceptance','verification':'Review verification scope'}
    for p in f['leaves']:
        text+=f"\n## {p['id']} — {p['name']}\n\n"
        rows=[]
        for k,label in labels.items():
            val=p[k]
            if k in ('code','tests') and not val: val='Unspecified / no implementation or executed test evidence claimed.'
            if isinstance(val,list): val=', '.join(val) or 'None'
            rows.append([label,val])
        rows.append(['Source sections', '; '.join(slink(source(x),prefix) for x in p['specifications'])+'; section IDs '+', '.join(p['evidence'])])
        if p['open_contract']: rows.append(['Unspecified mechanism','Exact wire/record schema, algorithm, quotas, compensation and executable tests remain unselected except where the cited contract explicitly fixes them. This gap prevents an implementation-complete leaf claim.'])
        text+=table(['Field','Definition'],rows)
    write(f"process-catalogue/{f['id']}.md",text)

classes={1:'Explicitly specified',2:'Logically derived',3:'Code-supported evidence',4:'Hypothesis',5:'Contradictory evidence',6:'Unspecified mechanism',7:'Deferred / future'}
write('evidence-register.md','# Evidence and authority register — Stage A\n\n'+
      'The baseline is the dirty working tree on 2026-10-26, not just HEAD. [Initial assessment](evidence/preliminary-assessment.md), [312 file hashes](evidence/baseline-files.json), [Git baseline](evidence/baseline-git-status.txt), [95-document inventory](evidence/document-inventory.csv), and [1,109 heading sections](evidence/sections.json) preserve provenance. Hashes describe reviewed bytes, not signatures or accepted requirements.\n\n'+
      'Owner decisions and explicitly adopted ADRs govern their stated scope. Inherited accepted obligations survive proposed editorial assembly. Historical implementation claims retain dates; later code does not silently replace intended design. ADR019 and the latest development checkpoint explicitly separate post-Commit replacement from text publication. Reserved IDs are not missing files accidentally omitted by this review. `.oldspecs/` remains ignored provenance, not an instruction source. No private runtime/manuscript/credential material was read or reproduced.\n\n'+
      'The section ledger is a mechanical source locator, not 1,109 independently accepted atomic claims. The following curated register contains semantic claims with classifications, status and process paths. Code-only observations are explicitly separated. Negative findings mean the scanned current contracts do not supply the mechanism, not that no future design could supply one.\n\n'+
      table(['Class','Meaning'],classes.items())+'\n'+
      '\n'.join(f"## {c['id']} — {classes[c['classification']]}\n\n{c['claim']}\n\nScope: {c['scope']}. Processes: {', '.join(c['processes'])}.\n\n"+table(['Exact source','Evidence locator'],[[slink(s),c['evidence'][i]] for i,s in enumerate(c['sources'])]) for c in claims))

rqrows=[]
for r in REQS:
    nums=requirement_families(r)
    paths=[f'HPX-PROC-{x:03d}' for x in nums]
    selected=['HPX-PROC-'+x for x in rqleaves[int(r['requirement_id'].split('-')[-1])]]
    leaves=[p for p in processes if p['id'] in selected]
    rqrows.append({'requirement':r['requirement_id'],'statement':r['statement_summary'],'design_processes':paths,
                   'leaf_processes':selected,'components':sorted(set(p['dependencies'] for p in leaves)),
                   'leaf_verification':[{'process':p['id'],'tests_or_scenarios':p['tests'] or 'Proposed contract/property/integration scenarios; no executable evidence claimed','milestone':p['status']} for p in leaves],
                   'original_design_refs':r['design_refs'],'original_code_refs':r['code_refs'],'original_test_refs':r['test_refs'],
                   'verification_path':'Review leaf invariants using cited tests; '+('future/mixed scope needs executable acceptance and mechanism decisions' if any(p['open_contract'] for p in leaves) else 'local evidence retains original reported scope'),
                   'gap':'Compound requirement needs atomic decomposition; historical register status is not current complete delivery.'})
dump('traceability/requirements.json',rqrows)
write('traceability/requirements.md','# Requirement paths and limits\n\nAll 31 registered requirement seeds have design paths below, including selected leaf responsibilities and component/test paths in the JSON. This is not 100% coverage of all normative sentences. Each row is compound; the leaf contracts and source-section ledger supplement it. Missing future mechanisms and stale delivery fields remain findings. Original code/test strings are retained as provenance, not claimed executions in this review.\n\n'+table(['Seed / original summary','Selected leaf processes','Original design / code / test evidence','Verification path / gap'],[[r['requirement']+' — '+r['statement'],', '.join(r['leaf_processes']),r['original_design_refs']+'; '+r['original_code_refs']+'; '+r['original_test_refs'],r['verification_path']+'; '+r['gap']] for r in rqrows]))

# Every registered contract gets a disposition; assurance/navigation are supporting views, not fictitious product processes.
docrows=[]
for d in DOCS:
    if d['materialized']!='yes': continue
    matched=[f['id'] for f in families if d['path'] in f['paths']]
    if not matched:
        lev=d['level'][:2]
        matched={'01':['HPX-PROC-010','HPX-PROC-011'],'02':['HPX-PROC-018'],'03':['HPX-PROC-018'],'04':['HPX-PROC-001','HPX-PROC-018'],'05':['HPX-PROC-005','HPX-PROC-006'],'06':['HPX-PROC-016'],'07':['HPX-PROC-018'],'08':['HPX-PROC-018'],'09':['HPX-PROC-018']}.get(lev,['HPX-PROC-018'])
        disposition='Supporting constraint / governance / assurance context; family-level mapping only'
    else: disposition='Direct process-contract source; inspect claim register for semantic scope'
    docrows.append({'id':d['id'],'path':d['path'],'processes':matched,'disposition':disposition})
dump('traceability/documents.json',docrows)
write('traceability/documents.md','# Registered-document dispositions\n\nMaterialized contracts each have a review path. Source indexing is exhaustive over Markdown; semantic implementation completeness is not. Reserved IDs are excluded from the denominator and remain open in the original inventory.\n\n'+table(['Document','Processes','Disposition'],[[d['id']+' — '+d['path'],', '.join(d['processes']),d['disposition']] for d in docrows]))

write('traceability/README.md','# Traceability navigation\n\n- [Requirement design and verification paths](requirements.md)\n- [Registered document dispositions](documents.md)\n- [Process contracts as JSON](process-model.json)\n- [Semantic claims and exact sources](../evidence-register.md)\n- [Cross-view checks](../validation-report.md)\n\nThe source requirement register has 31 compound seeds; this review does not turn them into 31 exhaustive atomic requirements. Family mappings express responsibility, not a claim that every leaf implements every seed. Future leaves expose missing interfaces instead of silently choosing them.\n')

print(json.dumps({'parents':len(families),'leaves':len(processes),'claims':len(claims),'requirement_paths':len(rqrows),'materialized_documents':len(docrows)}))
